5	namespace App\Tests\Acceptance\Legacy;
6	
7	use App\Identity\Infrastructure\Security\DemoCustomerProvider;
8	use App\Ordering\Domain\Model\Order;
9	use App\Ordering\Domain\Repository\OrderRepository;
10	use App\Ordering\Domain\ValueObject\CustomerId;
11	use App\Ordering\Domain\ValueObject\OrderId;
12	use App\Ordering\Domain\ValueObject\ProductId;
13	use App\SharedKernel\Domain\Currency;
14	use App\SharedKernel\Domain\Money;
15	use App\Tests\Support\Catalog;
16	use App\Tests\Support\TestDatabase;
17	use Doctrine\DBAL\Connection;
18	use Doctrine\ORM\EntityManagerInterface;
19	use PHPUnit\Framework\Attributes\Test;
20	use Symfony\Bundle\FrameworkBundle\KernelBrowser;
21	use Symfony\Bundle\FrameworkBundle\Test\WebTestCase;
22	
23	/**
24	 * Akceptační kritérium 1 z docs/plany/zmena-mnozstvi.md: množství jde změnit
25	 * jen u rozpracované objednávky, i ze staré administrace.
26	 */
27	final class ChangeItemQuantityTest extends WebTestCase
28	{
29	    private KernelBrowser $client;
30	
31	    protected function setUp(): void
32	    {
33	        TestDatabase::reset();
34	        // stará administrace drží spojení v globální proměnné
35	        $GLOBALS['db'] = null;
36	        $this->client = self::createClient();
37	        $this->client->disableReboot();
38	        Catalog::seed(self::getContainer()->get(Connection::class));
39	        $this->client->loginUser(
40	            self::getContainer()->get(DemoCustomerProvider::class)->loadUserByIdentifier('sprava@example.com'),
41	        );
42	    }
43	
44	    #[Test]
45	    public function quantityInConfirmedOrderStaysUnchanged(): void
46	    {
47	        // příprava: potvrzená objednávka, klávesnice 2 × 300 Kč, sleva 100 Kč
48	        $orders = self::getContainer()->get(OrderRepository::class);
49	        $order = Order::place(OrderId::generate(), CustomerId::generate());
50	        $order->addItem(ProductId::fromString(Catalog::KEYBOARD), 2, new Money(300_00, Currency::CZK));
51	        $order->applyDiscount(new Money(100_00, Currency::CZK));
52	        $order->confirm();
53	        $orders->save($order);
54	
55	        // akce: obsluha ve staré administraci změní množství na 3 kusy
56	        $this->client->request(
57	            'POST',
58	            '/admin/legacy/order_item_quantity?id='.$order->id->value,
59	            ['product' => Catalog::KEYBOARD, 'quantity' => '3'],
60	        );
61	
62	        // ověření: chyba, množství i částky beze změny
63	        self::assertSelectorTextContains('.flash.error', 'rozpracované objednávky');
64	        self::getContainer()->get(EntityManagerInterface::class)->clear();
65	        $unchanged = $orders->get($order->id);
66	        self::assertSame(2, $unchanged->items[0]->quantity);
67	        self::assertSame(600_00, $unchanged->totalAmount()->amountInCents);
68	        self::assertSame(500_00, $unchanged->paidAmount()->amountInCents);
69	    }
70	
71	    #[Test]
72	    public function quantityInDraftOrderChangesFromOrderDetail(): void
73	    {
74	        $order = Order::place(OrderId::generate(), CustomerId::generate());
75	        $order->addItem(ProductId::fromString(Catalog::KEYBOARD), 2, new Money(300_00, Currency::CZK));
76	        self::getContainer()->get(OrderRepository::class)->save($order);
77	
78	        $this->client->request('GET', '/admin/legacy/order?id='.$order->id->value);
79	        $this->client->submitForm('Změnit', ['quantity' => '3']);
80	
81	        self::assertSelectorTextContains('.flash', 'Množství položky změněno');
82	        self::getContainer()->get(EntityManagerInterface::class)->clear();
83	        self::assertSame(3, self::getContainer()->get(OrderRepository::class)->get($order->id)->items[0]->quantity);
84	    }
85	}
